   "titleVi": "… 與 … 相當 — tương đương với",
   "giaiThich": "Hai đối tượng có giá trị, điều kiện xấp xỉ nhau, cũng có ý \"xứng với nhau\". Trang trọng hơn 差不多; phía sau thường kèm nhận xét rõ ràng."
