   "titleVi": "一旦… 就/便… — một khi… thì…",
   "giaiThich": "Dùng cho việc CHƯA xảy ra: nếu có ngày điều kiện đó xuất hiện thì vế sau nêu kết quả hoặc cách xử lý. Giọng khách quan, suy luận chặt."
