     "formula": "「有A有B」的意思是「有A也有B」，兩者都有的意思。A與B都是單音節詞彙，本課的用法是兩個同性質的詞彙，但也常是同義詞或近義詞，形成四字格，有強調的作用。另外，也有由相反意思的單音節詞彙組成，代表衝突或對立的狀態。 使用「誰教」來強調因果關係，暗示行為者需要為結果負責。「誰教 N 一再⋯⋯的？」語氣較重，帶有指責意味。用於表達對某個人的行為或狀況的不滿，說話者希望能制止對方的行為，利用反問的語氣來強調做這件事根本不必要，有說話者認為不應該重複發生的意思。而「誰教 N 一再⋯⋯呢？」語氣較柔和，更像是感嘆或疑問，用於對某種行為的反思或討論。",
