   "titleVi": "Vs 於 — hơn / kém (so sánh)",
   "giaiThich": "\"A Vs 於 B\" nghĩa \"A … hơn B\"; sau 於 là đối tượng hoặc mốc so sánh. Tính từ thường là đơn âm: 多於, 少於, 高於, 低於, 大於, 小於."
