   "titleVi": "即便… 也… — cho dù… vẫn…",
   "giaiThich": "Liên từ nhượng bộ như 即使, nhưng giọng nhẹ hơn, thiên văn viết và KHÔNG đứng một mình được. Phần sau 也/都/還 mới là điều đáng lưu ý."
