   "titleVi": "在在 — mọi mặt đều",
   "giaiThich": "Nghĩa \"chỗ nào cũng, tất cả đều\": mọi điều kiện đều khớp hoặc đều cho thấy cùng một đặc điểm. Sau 在在 hay có 顯示, 表達, 表示, 指出 rồi tới kết quả."
