     "formula": "「可」有多種意思，在這裡是「可以、能夠、適合」的意思，需要注意的是前者與後者的 Vs 必為單音節相反詞彙，意思是可解釋成「有 Vs 有 Vs」、「可以有 A 也可以有 B 的成分或狀態」，有時候也代表「在客觀條件允許下，可在 A 與 B 之間的狀態或情況」。多用來指可以自由掌握其範圍或狀態的事物。 「比起⋯⋯，⋯⋯更⋯⋯」的句式為「比起A，B更⋯⋯」，也就是「A與B相比，B比A更⋯⋯」。這句型亦是比較句的一種，多半用來強調後者比前者的情況程度更高、更多。 sky lantern (miniature hot-air balloon used during festivals) Kongming Lantern (a kind of weather-proof portable lantern attributed to Zhuge Kongming) the old and weak, women and children as time passes, with the lapse of time (to act) on one's own initiative, spontaneously 「據說」是「根據傳說、聽說」的意思，也可以用在句中。雖然「據說」感覺起來有所依據，但其實並不一定有所根據，未必是真的，只是語氣會比「傳說」與「聽說」更肯定與真實。可以在「據說」之間插入別的詞語，如「據氣象預報說」。",
