   "titleVi": "可 A 可 B — vừa có thể A vừa có thể B",
   "giaiThich": "可 ở đây nghĩa \"có thể, phù hợp\". A và B phải là hai tính từ ĐƠN ÂM trái nghĩa; ý là có cả hai mặt, hoặc tuỳ điều kiện mà theo bên nào."
